549	            const r=e.getBoundingClientRect();
550	            const desc=e.querySelectorAll('*').length;
551	            if(!best || desc<best.desc) best={desc, x:Math.round(r.x+r.width/2), y:Math.round(r.y+r.height/2)};
552	        });
553	        return best;
554	    }""", text)
